body.script:
(function(){
  'use strict';

  var el = document.getElementById('dashData');
  var dailyData = [], weekdayData = [], formaPagoData = [];
  var pagosPuntuales = 0, pagosMora = 0, colorPuntual = '#0ca30c', colorMora = '#fab219';
  var STATE = { periodo: 'mes', fi: '', ff: '', cobradores: [] };

  if (el) {
    try { dailyData = JSON.parse(el.getAttribute('data-daily') || '[]'); } catch(e){}
    try { weekdayData = JSON.parse(el.getAttribute('data-weekday') || '[]'); } catch(e){}
    try { formaPagoData = JSON.parse(el.getAttribute('data-formapago') || '[]'); } catch(e){}
    pagosPuntuales = parseInt(el.getAttribute('data-puntuales') || '0', 10) || 0;
    pagosMora = parseInt(el.getAttribute('data-mora') || '0', 10) || 0;
    colorPuntual = el.getAttribute('data-color-puntual') || colorPuntual;
    colorMora = el.getAttribute('data-color-mora') || colorMora;
    STATE.periodo = el.getAttribute('data-periodo') || 'mes';
    STATE.fi = el.getAttribute('data-fi') || '';
    STATE.ff = el.getAttribute('data-ff') || '';
    var cobStr = el.getAttribute('data-cobradores') || '';
    STATE.cobradores = cobStr ? cobStr.split(',').filter(function(x){ return x; }) : [];
  }

  function markActiveTab() {
    ['dia','semana','mes'].forEach(function(p){
      var btn = document.getElementById('tab' + p.charAt(0).toUpperCase() + p.slice(1));
      if (btn) btn.classList.toggle('active', STATE.periodo === p);
    });
    var rangoBtn = document.getElementById('tabRango');
    if (rangoBtn) {
      rangoBtn.classList.toggle('active', STATE.periodo === 'rango');
      rangoBtn.innerHTML = STATE.periodo === 'rango'
        ? '📅 Rango · ' + STATE.fi + ' → ' + STATE.ff
        : '📅 Rango';
    }
    var cobBtn = document.getElementById('cobradorTrigger');
    if (cobBtn) cobBtn.classList.toggle('has-filter', STATE.cobradores.length > 0);
  }

  function goTo() {
    var url = '/web/dashboard/cobranzas?periodo=' + encodeURIComponent(STATE.periodo);
    if (STATE.periodo === 'rango' && STATE.fi && STATE.ff) {
      url += '&fecha_inicio=' + encodeURIComponent(STATE.fi) + '&fecha_fin=' + encodeURIComponent(STATE.ff);
    }
    if (STATE.cobradores.length) {
      url += '&cobradores=' + encodeURIComponent(STATE.cobradores.join(','));
    }
    window.location.href = url;
  }

  window.setPeriodo = function(p) {
    STATE.periodo = p;
    goTo();
  };

  /* ── RANGE PICKER ─────────────────────────────────────────── */
  window.openRangePicker = function() {
    document.getElementById('rpInputStart').value = STATE.fi;
    document.getElementById('rpInputEnd').value = STATE.ff;
    document.getElementById('rpOverlay').classList.add('open');
  };
  function initRangePicker() {
    document.getElementById('rpBtnCancel').addEventListener('click', function() {
      document.getElementById('rpOverlay').classList.remove('open');
    });
    document.getElementById('rpBtnApply').addEventListener('click', function() {
      var s = document.getElementById('rpInputStart').value;
      var e = document.getElementById('rpInputEnd').value;
      if (!s || !e) { alert('Selecciona ambas fechas'); return; }
      if (s > e) { alert('La fecha inicio debe ser menor o igual a la fecha fin'); return; }
      STATE.periodo = 'rango';
      STATE.fi = s;
      STATE.ff = e;
      goTo();
    });
    document.getElementById('rpOverlay').addEventListener('click', function(ev) {
      if (ev.target === this) this.classList.remove('open');
    });
  }

  /* ── COBRADOR PICKER ──────────────────────────────────────── */
  window.openCobradorPicker = function() {
    document.getElementById('cfOverlay').classList.add('open');
  };
  window.filterCobradorList = function() {
    var q = (document.getElementById('cfSearch').value || '').toLowerCase();
    document.querySelectorAll('#cfList .cf-item').forEach(function(item){
      var name = item.getAttribute('data-name') || '';
      item.style.display = (!q || name.indexOf(q) !== -1) ? 'flex' : 'none';
    });
  };
  function initCobradorPicker() {
    document.getElementById('cfBtnCancel').addEventListener('click', function() {
      document.getElementById('cfOverlay').classList.remove('open');
    });
    document.getElementById('cfSelectAll').addEventListener('click', function() {
      document.querySelectorAll('#cfList .cf-checkbox').forEach(function(cb){ cb.checked = true; });
    });
    document.getElementById('cfClearAll').addEventListener('click', function() {
      document.querySelectorAll('#cfList .cf-checkbox').forEach(function(cb){ cb.checked = false; });
    });
    document.getElementById('cfBtnApply').addEventListener('click', function() {
      var ids = [];
      document.querySelectorAll('#cfList .cf-checkbox').forEach(function(cb){
        if (cb.checked) ids.push(cb.value);
      });
      STATE.cobradores = ids;
      goTo();
    });
    document.getElementById('cfOverlay').addEventListener('click', function(ev) {
      if (ev.target === this) this.classList.remove('open');
    });
  }

  /* ── TOOLTIP ──────────────────────────────────────────────── */
  var _tip = null;
  var _S = '\x3C', _E = '\x3E';
  function fmt(n){ return 'S/ ' + parseFloat(n).toLocaleString('es-PE', {minimumFractionDigits:2, maximumFractionDigits:2}); }

  window.showTip = function(e, node) {
    if (!_tip) _tip = document.getElementById('rcTooltip');
    if (!_tip) return;
    var label = node.getAttribute('data-label') || '';
    var monto = node.getAttribute('data-monto');
    var value = node.getAttribute('data-value');
    var pagos = node.getAttribute('data-pagos');
    var pct   = node.getAttribute('data-pct');
    var amount = monto !== null ? monto : value;
    var html = _S+'div style="font-weight:700;color:#f1f5f9;margin-bottom:4px;"'+_E+label+_S+'/div'+_E;
    if (amount !== null) {
      html += _S+'div style="font-size:1rem;font-weight:800;color:#38bdf8;"'+_E+fmt(amount)+_S+'/div'+_E;
    }
    if (pagos !== null) {
      html += _S+'div style="font-size:.72rem;color:#94a3b8;"'+_E+pagos+' pago(s)'+_S+'/div'+_E;
    }
    if (pct !== null) {
      html += _S+'div style="font-size:.72rem;color:#94a3b8;"'+_E+pct+'% del total'+_S+'/div'+_E;
    }
    _tip.innerHTML = html;
    _tip.style.display = 'block';
    window.moveTip(e);
  };
  window.moveTip = function(e) {
    if (!_tip || _tip.style.display === 'none') return;
    var x = e.clientX + 14, y = e.clientY - 10;
    if (x + 170 > window.innerWidth)  x = e.clientX - 180;
    if (y + 90  > window.innerHeight) y = e.clientY - 100;
    _tip.style.left = x + 'px';
    _tip.style.top  = y + 'px';
  };
  window.hideTip = function() {
    if (!_tip) _tip = document.getElementById('rcTooltip');
    if (_tip) _tip.style.display = 'none';
  };

  /* ── GENERIC BAR SERIES CHART (SVG) ──────────────────────── */
  function buildBarSeries(containerId, data, color, opts) {
    var container = document.getElementById(containerId);
    if (!container || !data.length) return;
    opts = opts || {};
    var H = opts.height || 240;
    var padL = 58, padR = 18, padT = 20, padB = 40;
    var n = data.length;
    var scrollMode = !!opts.scroll;
    var wrapWidth = container.parentElement.clientWidth || 600;
    var groupW = scrollMode
      ? Math.max(38, Math.floor((wrapWidth - padL - padR) / n))
      : Math.max(60, Math.floor((wrapWidth - padL - padR) / n));
    var W = padL + groupW * n + padR;
    var chartH = H - padT - padB;
    var barW = Math.max(10, Math.min(30, groupW * 0.48));

    var maxVal = 0;
    data.forEach(function(d){ if (d.monto > maxVal) maxVal = d.monto; });
    if (maxVal === 0) maxVal = 1;

    var p = [];
    p.push('<svg xmlns="http://www.w3.org/2000/svg" width="'+W+'" height="'+H+'" style="display:block;">');

    for (var s = 0; s <= 4; s++) {
      var yg = padT + chartH - (s / 4) * chartH;
      var val = (s / 4) * maxVal;
      var vlbl = val >= 1000 ? (val / 1000).toFixed(1) + 'k' : val.toFixed(0);
      p.push('<line x1="'+padL+'" y1="'+yg+'" x2="'+(W-padR)+'" y2="'+yg+'" stroke="rgba(51,65,85,.55)" stroke-width="1"/>');
      p.push('<text x="'+(padL-8)+'" y="'+(yg+4)+'" text-anchor="end" font-size="9" fill="#64748b">'+vlbl+'</text>');
    }

    data.forEach(function(d, i){
      var cx = padL + (i + 0.5) * groupW;
      var h = (d.monto / maxVal) * chartH;
      var x = cx - barW / 2;
      var y = padT + chartH - h;
      var label = d.fecha || d.dia || '';
      if (h > 0) {
        p.push('<rect x="'+x+'" y="'+y+'" width="'+barW+'" height="'+h+'" rx="4" fill="'+color+'"'
          +' data-label="'+label+'" data-monto="'+d.monto+'" data-pagos="'+(d.pagos||0)+'"'
          +' style="cursor:pointer;transition:opacity .15s"'
          +' onmouseenter="showTip(event,this)" onmousemove="moveTip(event)" onmouseleave="hideTip()"/>');
      }
      var shortLbl = opts.dayLabels ? label.slice(0,3) : label.slice(0,5);
      p.push('<text x="'+cx+'" y="'+(H-8)+'" text-anchor="middle" font-size="9" fill="#64748b">'+shortLbl+'</text>');
    });

    p.push('</svg>');

    if (scrollMode) container.style.width = W + 'px';
    container.innerHTML = p.join('').replace(/</g,'\x3C').replace(/>/g,'\x3E');
  }

  /* ── GENERIC MULTI-SLICE DONUT (SVG) ─────────────────────── */
  function buildDonutMulti(containerId, slices, opts) {
    var container = document.getElementById(containerId);
    if (!container) return;
    opts = opts || {};
    var total = 0;
    slices.forEach(function(s){ total += s.value; });
    if (total <= 0) return;

    var R = 70, r = 46, cx = 95, cy = 95, size = 190;
    var circ = 2 * Math.PI * R;
    var offset = circ * 0.25;
    var acc = 0;
    var gap = slices.length > 1 ? 2 : 0;

    var parts = [];
    parts.push('<svg xmlns="http://www.w3.org/2000/svg" width="'+size+'" height="'+size+'">');
    parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="'+R+'" fill="none" stroke="#334155" stroke-width="'+(R-r)+'"/>');

    slices.forEach(function(s){
      var frac = s.value / total;
      var len = frac * circ;
      var dash = Math.max(len - gap, 0);
      parts.push('<circle cx="'+cx+'" cy="'+cy+'" r="'+R+'" fill="none" stroke="'+s.color+'" stroke-width="'+(R-r)+'"'
        +' stroke-dasharray="'+dash+' '+(circ-dash)+'"'
        +' stroke-dashoffset="'+(offset-acc)+'"'
        +' data-label="'+s.label+'" data-value="'+s.value+'" data-pct="'+(frac*100).toFixed(1)+'"'
        +' style="cursor:pointer"'
        +' onmouseenter="showTip(event,this)" onmousemove="moveTip(event)" onmouseleave="hideTip()"'
        +' transform="rotate(-90 '+cx+' '+cy+')"/>');
      acc += len;
    });

    if (opts.centerValue) {
      parts.push('<text x="'+cx+'" y="'+(cy-4)+'" text-anchor="middle" font-size="17" font-weight="800" fill="'+(opts.centerColor||'#e2e8f0')+'">'+opts.centerValue+'</text>');
      parts.push('<text x="'+cx+'" y="'+(cy+14)+'" text-anchor="middle" font-size="9" fill="#64748b">'+(opts.centerLabel||'')+'</text>');
    }

    parts.push('</svg>');
    container.innerHTML = parts.join('').replace(/</g,'\x3C').replace(/>/g,'\x3E');
  }

  /* ── TABLE: SEARCH + FILTER + PAGINATION ─────────────────── */
  var PAGE_SIZE = 20;
  var currentPage = 1;

  function getFilteredRows() {
    var search = ((document.getElementById('tableSearch') || {}).value || '').toLowerCase();
    var filter = (document.getElementById('tableFilter') || {}).value || 'all';
    var rows = document.querySelectorAll('#payTable tbody tr');
    var visible = [];
    rows.forEach(function(row){
      var tipo = row.getAttribute('data-tipo') || '';
      var text = row.getAttribute('data-search') || '';
      var match = (filter === 'all' || tipo === filter) && (!search || text.indexOf(search) !== -1);
      if (match) visible.push(row);
    });
    return visible;
  }

  function renderPage(page) {
    currentPage = page;
    var allRows = document.querySelectorAll('#payTable tbody tr');
    var filtered = getFilteredRows();
    var total = filtered.length;
    var totalPages = Math.max(1, Math.ceil(total / PAGE_SIZE));
    if (currentPage > totalPages) currentPage = totalPages;
    var start = (currentPage - 1) * PAGE_SIZE;
    var end = start + PAGE_SIZE;

    allRows.forEach(function(r){ r.style.display = 'none'; });
    filtered.forEach(function(r, i){
      r.style.display = (i >= start && i < end) ? '' : 'none';
    });

    var infoEl = document.getElementById('pageInfo');
    if (infoEl) {
      var from = total === 0 ? 0 : start + 1;
      var to = Math.min(end, total);
      infoEl.textContent = 'Mostrando ' + from + ' - ' + to + ' de ' + total + ' pagos';
    }

    var btnsEl = document.getElementById('pageBtns');
    if (!btnsEl) return;
    var html = [];

    if (currentPage > 1) {
      html.push(_S+'button class="page-btn" onclick="renderPage('+(currentPage-1)+')"'+_E+'←'+_S+'/button'+_E);
    }
    var winStart = Math.max(1, currentPage - 2);
    var winEnd = Math.min(totalPages, currentPage + 2);
    if (winStart > 1) {
      html.push(_S+'button class="page-btn" onclick="renderPage(1)"'+_E+'1'+_S+'/button'+_E);
      if (winStart > 2) html.push(_S+'span style="color:#475569;padding:0 4px;"'+_E+'...'+_S+'/span'+_E);
    }
    for (var pg = winStart; pg <= winEnd; pg++) {
      var active = pg === currentPage ? ' active' : '';
      html.push(_S+'button class="page-btn'+active+'" onclick="renderPage('+pg+')"'+_E+pg+_S+'/button'+_E);
    }
    if (winEnd < totalPages) {
      if (winEnd < totalPages - 1) html.push(_S+'span style="color:#475569;padding:0 4px;"'+_E+'...'+_S+'/span'+_E);
      html.push(_S+'button class="page-btn" onclick="renderPage('+totalPages+')"'+_E+totalPages+_S+'/button'+_E);
    }
    if (currentPage < totalPages) {
      html.push(_S+'button class="page-btn" onclick="renderPage('+(currentPage+1)+')"'+_E+'→'+_S+'/button'+_E);
    }
    btnsEl.innerHTML = html.join('');
  }
  window.renderPage = renderPage;
  window.filterTable = function(){ renderPage(1); };

  /* ── INIT ─────────────────────────────────────────────────── */
  function buildAllCharts() {
    buildBarSeries('dailyChartSvg', dailyData, '#38bdf8', { scroll: true, height: 240 });
    buildBarSeries('weekdayChartSvg', weekdayData, '#f59e0b', { scroll: false, height: 220, dayLabels: true });
    buildDonutMulti(
      'formaPagoSvg',
      formaPagoData.map(function(d){ return { label: d.forma, value: d.monto, color: d.color, pagos: d.pagos }; }),
      {}
    );
    var totalPunt = pagosPuntuales + pagosMora;
    var pctPunt = totalPunt ? Math.round((pagosPuntuales / totalPunt) * 100) : 0;
    buildDonutMulti(
      'puntualidadSvg',
      [
        { label: 'A tiempo', value: pagosPuntuales, color: colorPuntual, pagos: pagosPuntuales },
        { label: 'Con mora', value: pagosMora, color: colorMora, pagos: pagosMora }
      ],
      { centerValue: pctPunt + '%', centerLabel: 'a tiempo', centerColor: colorPuntual }
    );
  }

  function init() {
    markActiveTab();
    buildAllCharts();
    renderPage(1);
    initRangePicker();
    initCobradorPicker();
  }

  if (document.readyState === 'loading') { document.addEventListener('DOMContentLoaded', init); }
  else { init(); }
  window.addEventListener('resize', buildAllCharts);

})();
